-- History pivot / #182: Grécia e Roma Antigas
-- Generated by generators/emit_trail_sql.py from generators/trail_grecia_roma.py.
-- Idempotent. One transaction. Pair with matching .rollback.sql.
-- DO NOT apply without owner go-ahead. Dry-run with BEGIN + RAISE EXCEPTION.

BEGIN;

INSERT INTO public.modulos (ordem, titulo, emoji, cor, categoria_id, descricao)
SELECT 20, 'Grécia e Roma Antigas', '🏺', '#CA8A04', 1, 'Da pólis grega ao Império Romano: cidadania, expansão, crise e o legado que ainda organiza o Ocidente.'
WHERE NOT EXISTS (SELECT 1 FROM public.modulos WHERE titulo = 'Grécia e Roma Antigas');

CREATE TEMP TABLE _seed_trail AS
SELECT id AS modulo_id FROM public.modulos WHERE titulo = 'Grécia e Roma Antigas';

INSERT INTO public.niveis (modulo_id, ordem, titulo)
SELECT t.modulo_id, v.ordem, v.titulo
FROM _seed_trail t
CROSS JOIN (VALUES
  (1, 'Nível 1 - Pólis e o mundo grego'),
  (2, 'Nível 2 - Roma republicana'),
  (3, 'Nível 3 - Império e transformação'),
  (4, 'Nível 4 - Queda, Bizâncio e legado')
) AS v(ordem, titulo)
WHERE NOT EXISTS (
  SELECT 1 FROM public.niveis n WHERE n.modulo_id = t.modulo_id AND n.ordem = v.ordem
);

INSERT INTO public.submodulos (modulo_id, nivel_id, ordem, titulo, data_liberacao_desde_inicio, imagem_url)
SELECT t.modulo_id, n.id, v.ordem, v.titulo, 0, NULL
FROM _seed_trail t
CROSS JOIN (VALUES
  (1, 1, 'Pólis e cidadania em Atenas'),
  (1, 2, 'Esparta e a sociedade militar'),
  (1, 3, 'De Maratona a Alexandre'),
  (2, 4, 'República romana e o Senado'),
  (2, 5, 'Escravidão, cidadania e expansão'),
  (2, 6, 'César, Augusto e o Principado'),
  (3, 7, 'Pax Romana e a vida urbana'),
  (3, 8, 'Cristianismo no Império'),
  (3, 9, 'Crise do século III'),
  (4, 10, 'Queda no Ocidente'),
  (4, 11, 'Bizâncio e a continuidade'),
  (4, 12, 'Legado: direito, língua e política')
) AS v(nivel_ordem, ordem, titulo)
JOIN public.niveis n ON n.modulo_id = t.modulo_id AND n.ordem = v.nivel_ordem
WHERE NOT EXISTS (
  SELECT 1 FROM public.submodulos s WHERE s.modulo_id = t.modulo_id AND s.ordem = v.ordem
);

INSERT INTO public.licoes (submodulo_id, ordem, titulo, emoji, conteudo)
SELECT s.id, 1, s.titulo, '🏺',
       jsonb_build_object('preview', v.preview)
FROM _seed_trail t
JOIN public.submodulos s ON s.modulo_id = t.modulo_id
JOIN (VALUES
  (1, 'A democracia ateniense do século V a.C. era direta para cidadãos homens adultos — e excluía mulheres, estrangeiros e escravizados, a maior parte da população. O ágora concentrava política e comércio; o ostracismo afastava líderes temidos sem julgamento criminal. Cleistenes reorganizou as tribos para enfraquecer clãs aristocráticos, e Péricles ligou a cidadania ao serviço público remunerado.'),
  (2, 'Esparta era uma oligarquia dual com dois reis, um conselho de anciãos (gerúsia) e a assembleia dos espartiatas. A agogê treinava meninos para a guerra; os hilotas, população submetida da Messênia, sustentavam a elite com trabalho agrícola sob vigilância constante. Termópilas virou mito de sacrifício, mas a força espartana também dependia de aliados e de um sistema social rígido que temia reformas.'),
  (3, 'As Guerras Médicas (início do século V a.C.) uniram pólis rivais contra o Império Persa: Maratona, Salamina e Plateia entraram na memória grega como vitórias da liberdade — com muita propaganda. Depois, a Guerra do Peloponeso esgotou Atenas e Esparta. No século IV, a Macedônia de Filipe II e Alexandre impôs hegemonia e espalhou o grego helenístico até o Indo.'),
  (4, 'Após a expulsão dos reis etruscos (tradição: 509 a.C.), Roma organizou uma República com cônsules anuais, magistraturas e um Senado de aristocratas. O conflito patrícios-plebeus produziu tribunos e o acesso gradual às magistraturas. As Doze Tábuas fixaram direito escrito; a expansão itálica criou uma rede de aliados com status jurídicos diferentes — não um Estado nacional moderno.'),
  (5, 'A conquista do Mediterrâneo trouxe riqueza, escravizados e crises sociais. Cidadania romana era privilégio jurídico progressivamente estendido; socii italianos pediram direitos na Guerra Social (91–88 a.C.). Latifúndios com trabalho escravo pressionaram pequenos camponeses-soldados. Os Gracos tentaram reformas agrárias e morreram na violência política que antecipou o fim da República.'),
  (6, 'Guerras civis do século I a.C. destruíram o equilíbrio republicano: Mário e Sila, o Primeiro Triunvirato, César ditador vitalício assassinado em 44 a.C., depois Otaviano vence Ácio (31 a.C.). Como Augusto, mantém fachada republicana — Senado, magistraturas — mas concentra o poder real no Principado. A ''restauração da República'' foi a fundação do Império.'),
  (7, 'Nos dois primeiros séculos d.C., o Império viveu relativa estabilidade nas fronteiras internas do Mediterrâneo: estradas, direito, cidades com fóruns, termas e aquedutos. A paz era romana e desigual — legiões nas fronteiras, escravidão, e revoltas como a judaica. Cidadania se expandiu até a Constitutio Antoniniana (212), que estendeu o status a homens livres do Império, sobretudo por razões fiscais.'),
  (8, 'O cristianismo nasceu no judaísmo do século I, sob domínio romano. Perseguições foram intermitentes, não constantes. Constantino legalizou o culto (Editais de 313) e convocou Niceia (325); Teodósio tornou o cristianismo niceno religião oficial no fim do século IV. A Igreja herdou redes urbanas do Império e se tornou instituição política decisiva na Antiguidade Tardia.'),
  (9, 'Entre 235 e 284, Roma viveu a Anarquia Militar: dezenas de imperadores, invasões, peste e inflação. O Império quase se fragmentou (Império das Gálias, Palmira). Diocleciano reorganizou a Tetrarquia, reforçou impostos e a burocracia. A crise mostrou que o Principado augustano já não sustentava um Império sob pressão externa e interna simultâneas.'),
  (10, 'Em 476, Odoacro depôs Rômulo Augústulo em Ravena — marco convencional do fim do Império no Ocidente, não o ''apagão'' da civilização. Muito antes, saques (Alarico em 410), perda fiscal e o uso crescente de chefes germânicos no exército já tinham transformado o poder. Reinos romano-germânicos preservaram cidades, latim e instituições locais em graus variados.'),
  (11, 'O Império Romano do Oriente — que chamamos Bizâncio — sobreviveu até 1453. Justiniano (século VI) reconquistou partes do Ocidente e codificou o direito (Corpus Juris Civilis). Grego tornou-se língua administrativa; Constantinopla era a maior cidade cristã da Idade Média inicial. Falar em ''queda de Roma'' em 476 apaga mil anos de Roma oriental.'),
  (12, 'Do direito romano às línguas românicas, do calendário juliano ao imaginário republicano e imperial, Grécia e Roma moldaram categorias políticas do Ocidente. Filosofia grega e retórica alimentaram escolas; o latim foi língua culta por séculos. Esse legado foi seletivo: escravidão, exclusão de mulheres e imperialismo também fazem parte da herança, não só colunas e discursos sobre liberdade.')
) AS v(sub_ordem, preview) ON v.sub_ordem = s.ordem
WHERE NOT EXISTS (SELECT 1 FROM public.licoes l WHERE l.submodulo_id = s.id);

